import { Splitter, Card } from "march/ui"

// önce / sonra: iki renk alanı arasında tutamaç; pay yüzde olarak yazılır
export function BeforeAfter() {
  let $share = 0.5
  return <Card m:theme="night">
    <div style={{ "block-size": "14rem" }}>
      <Splitter initial={0.5} min={0.1} label="Karşılaştırma" m:color="brand-orange" onChange={(s: number) => $share = s}
        start={<div sx={{ p: 4, flex: "center", text: ["lg", "bold"], color: "brand-blue" }}>Önce</div>}
        end={<div sx={{ p: 4, flex: "center", text: ["lg", "bold"], color: "brand-orange" }}>Sonra</div>} />
    </div>
    <span sx={{ text: "sm", color: "muted" }}>Önce: %{Math.round($share * 100)}</span>
  </Card>
}

import { Splitter, ListRow } from "march/ui"
import { mail } from "march/icons"

// e-posta istemcisi: solda gelen kutusu, sağda seçilen ileti; liste payı kaydırılabilir
const inbox = [
  { from: "Elif", subject: "Toplantı notları", body: "Yarınki toplantının notlarını ekte bulabilirsin." },
  { from: "Can", subject: "Tasarım taslağı", body: "Yeni ana sayfa taslağına bakar mısın?" },
  { from: "Deniz", subject: "Fatura", body: "Kasım faturası hazır." },
]

export function MailClient() {
  let $open = 0
  return <div style={{ "block-size": "14rem" }} class="m-card">
    <Splitter initial={0.4} min={0.25} label="Gelen kutusu genişliği"
      start={<div>{inbox.map((m, i) => <ListRow icon={mail} title={m.from} subtitle={m.subject} on:click={() => $open = i} />)}</div>}
      end={<div sx={{ p: 4 }}><h4 sx={{ text: "bold" }}>{inbox[$open]!.subject}</h4><p>{inbox[$open]!.body}</p></div>} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { SplitterLab } from "./SplitterLab.tsx"

// SplitterLab'in testleri: kaydedince Testler sekmesinde çalışır
test("tutamaç bir ayırıcı: adı ve değeri var", () => {
  const s = renderTest(() => <SplitterLab />)
  const sep = s.get(".lab-live [role=separator]")
  expect(sep?.getAttribute("aria-label")).toBe("Denetimli pay")
  expect(sep?.getAttribute("aria-valuenow")).toBe("30")
})

test("value denetimli: düğme payı değiştirir", async () => {
  const s = renderTest(() => <SplitterLab />)
  await s.click("Payı %70 yap")
  expect(s.get(".lab-share")?.textContent).toBe("%70")
})

test("handle={false} sürüklenmeyen düz bir ayraç bırakır", () => {
  const s = renderTest(() => <SplitterLab />)
  expect(s.get(".lab-fixed .m-split-handle")?.classList.contains("is-fixed")).toBe(true)
  expect(s.get(".lab-fixed [role=separator]")?.hasAttribute("aria-valuenow")).toBe(false)
})
